[{"order":1,"type":"heading","text":"Template Engines in Node.js: Pug, EJS, and Handlebars"},{"order":2,"type":"paragraph","text":"Template engines are essential tools for building dynamic web applications with Node.js. They allow you to separate the presentation layer (HTML) from the application logic, making your code more maintainable and easier to understand. This tutorial explores three popular template engines: Pug, EJS, and Handlebars."},{"order":3,"type":"subheading","text":"Why Use a Template Engine?"},{"order":4,"type":"bullet_point","text":"Separation of Concerns: Keep your HTML structure separate from your JavaScript code."},{"order":5,"type":"bullet_point","text":"Code Reusability: Create reusable templates and partials."},{"order":6,"type":"bullet_point","text":"Dynamic Content: Easily inject data into your HTML templates."},{"order":7,"type":"bullet_point","text":"Improved Maintainability: Changes to the presentation layer don't require modifications to the application logic, and vice versa."},{"order":8,"type":"subheading","text":"Pug (formerly Jade)"},{"order":9,"type":"paragraph","text":"Pug is a concise and readable template engine known for its clean syntax. It uses indentation instead of closing tags, making it very compact."},{"order":10,"type":"code","text":"// Installation:
npm install pug"},{"order":11,"type":"code","text":"// Example Pug template (index.pug):
doctype html
html(lang='en')
  head
    title Pug Template
  body
    h1 Hello, #{name}!"},{"order":12,"type":"code","text":"// Node.js usage:
const pug = require('pug');
const http = require('http');

const compiledFunction = pug.compileFile('index.pug');

const server = http.createServer((req, res) => {
  const html = compiledFunction({ name: 'World' });
  res.writeHead(200, { 'Content-Type': 'text/html' });
  res.end(html);
});

server.listen(3000, () => {
  console.log('Server listening on port 3000');
});"},{"order":13,"type":"subheading","text":"EJS (Embedded JavaScript templates)"},{"order":14,"type":"paragraph","text":"EJS allows you to embed JavaScript directly into your HTML. It's a simple and flexible template engine that's easy to learn."},{"order":15,"type":"code","text":"// Installation:
npm install ejs"},{"order":16,"type":"code","text":"// Example EJS template (index.ejs):
<!DOCTYPE html>
<html lang="en">
<head>
  <title>EJS Template</title>
</head>
<body>
  <h1>Hello, <%= name %>!</h1>
</body>
</html>"},{"order":17,"type":"code","text":"// Node.js usage:
const ejs = require('ejs');
const http = require('http');
const fs = require('fs').promises;

const server = http.createServer(async (req, res) => {
  const template = await fs.readFile('index.ejs', 'utf8');
  const html = ejs.render(template, { name: 'World' });
  res.writeHead(200, { 'Content-Type': 'text/html' });
  res.end(html);
});

server.listen(3000, () => {
  console.log('Server listening on port 3000');
});"},{"order":18,"type":"subheading","text":"Handlebars"},{"order":19,"type":"paragraph","text":"Handlebars is a semantic templating engine that uses double curly braces {{...}} for expressions. It emphasizes logic-less templates, promoting cleaner separation of concerns."},{"order":20,"type":"code","text":"// Installation:
npm install handlebars"},{"order":21,"type":"code","text":"// Example Handlebars template (index.handlebars):
<!DOCTYPE html>
<html lang="en">
<head>
  <title>Handlebars Template</title>
</head>
<body>
  <h1>Hello, {{name}}!</h1>
</body>
</html>"},{"order":22,"type":"code","text":"// Node.js usage:
const handlebars = require('handlebars');
const http = require('http');
const fs = require('fs').promises;

const server = http.createServer(async (req, res) => {
  const template = await fs.readFile('index.handlebars', 'utf8');
  const compiledTemplate = handlebars.compile(template);
  const html = compiledTemplate({ name: 'World' });
  res.writeHead(200, { 'Content-Type': 'text/html' });
  res.end(html);
});

server.listen(3000, () => {
  console.log('Server listening on port 3000');
});"},{"order":23,"type":"subheading","text":"Choosing the Right Template Engine"},{"order":24,"type":"bullet_point","text":"Pug: Best for concise syntax and clean HTML generation."},{"order":25,"type":"bullet_point","text":"EJS: Best for simplicity and direct JavaScript embedding."},{"order":26,"type":"bullet_point","text":"Handlebars: Best for logic-less templates and complex data transformations."},{"order":27,"type":"paragraph","text":"Ultimately, the best template engine depends on your project's specific needs and your personal preferences. Experiment with each to find the one that suits you best."}]
